INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(21500, 0, 215, 0, 0, 0, 'Mulgore', 'Mulgore is the homeland of the tauren, a sheltered valley of golden grass and gentle hills ringed by mountains on the western edge of the Barrens. The tauren once wandered as nomads, harried by the centaur, until Cairne Bloodhoof, aided by Thrall and his orcs, led his people here, drove the centaur back and claimed the plains. On a towering mesa in the north he raised Thunder Bluff as a refuge for every tribe, and the scattered tribes came together under his rule. Young tauren come of age at Camp Narache on Red Cloud Mesa and at Bloodhoof Village by Stonebull Lake, proving themselves through the Rites of the Earthmother and the honor of the hunt. Their peace is far from complete. Bristleback quilboar raid from their ravine and even trouble the sacred graves at Red Rocks, Palemane gnolls slaughter the wildlife, Windfury harpies nest along the mountains, dwarves dig into the western hills, and goblins of the Venture Company have poisoned the sacred wells in their hunger for ore.', 'warcraft.wiki.gg/wiki/Mulgore (Warcraft III section: Cairne led the tauren to Mulgore with Thrall''s help, centaur driven back, Thunder Bluff founded as a refuge for every tribe, tribes united; enemies of the WoW era); quest 763 description (Rites of the Earthmother); quest 833 description (Red Rocks); quest 745 description (Palemane); quest 748 description (goblins tainted the sacred wells); quest 746 description (dwarven dig); quest 743 description (Windfury harpies)'),
(21501, 1, 215, 1, 0, 0, 'Camp Narache', 'Camp Narache stands at the northern edge of Red Cloud Mesa, high above the plains of southern Mulgore, and here young tauren take their first steps toward adulthood. Chief Hawkwind presides over the camp and reminds every eager newcomer that eagerness is no substitute for wisdom. His son Grull sends novices out to hunt for the tribe''s meat, feathers and pelts, while trainers of warriors, hunters, druids and shamans gather in the camp to guide those who follow each path. Seer Ravenfeather readies young shamans for the call of the earth, and the warrior Harutt Thunderhorn teaches that his kind are the ones called upon to defend the borders, hunt the centaur and go to war.', 'zone_areas 221: Chief Hawkwind 2981, Grull Hawkwind 2980, trainers Harutt Thunderhorn, Lanka Farshot, Gart Mistrunner, Meela Dawnstrider, Seer Ravenfeather; quest_greeting 2981; quests 747, 750 (Grull, hunts); quest 3091 request text (Harutt); quest 1519 (Ravenfeather); warcraft.wiki.gg/wiki/Camp_Narache and Red_Cloud_Mesa (northwest of the mesa)'),
(21502, 1, 215, 2, 0, 0, 'Red Cloud Mesa', 'Red Cloud Mesa is a high plateau of rolling grassland atop sheer cliffs in the far south of Mulgore. Plainstriders graze across it, mountain cougars prowl the hills to the south, and battleboars trained by the Bristleback quilboar roam out of the ravine to the east to raid the tauren hunting grounds. A water well lies southeast of Camp Narache, and there Greatmother Hawkwind, the chief''s aged mother, goes to draw water at her own unhurried pace. Tucked into the hills directly south of the camp is the abode of Seer Graytongue, who sets young tauren their first test of strength. The mesa is a proving ground, and those who pass its trials follow the road down to Bloodhoof Village.', 'warcraft.wiki.gg/wiki/Red_Cloud_Mesa (plateau of rolling plains atop high cliffs in southern Mulgore); quests 747, 750, 780 (plainstriders, cougars in the hills to the south, battleboars trained by the Bristlebacks); quests 752, 753 (Greatmother at the well southeast of Narache); quests 755, 757 (Seer Graytongue south of the camp, Rite of Strength); quest 763 (road to Bloodhoof); zone_areas 220: Greatmother Hawkwind 2991, Seer Graytongue 2982, Water Pitcher objects'),
(21503, 1, 215, 3, 0, 0, 'Brambleblade Ravine', 'East of Camp Narache, Brambleblade Ravine is the home of the Bristleback quilboar, who have built a makeshift village there and wage a stubborn war on the tauren from it. Bristleback raiders ambush hunting parties and steal from the camp under cover of darkness, their shamans keep a ritual salve of their own making, and their battleboars are trained to viciousness. At the back of the ravine their leader, Chief Sharptusk Thornmantle, keeps his own large hut, and somewhere among the quilboar dwellings lies a dirt-stained map.', 'quest 757 description (ambush hunting parties, steal from the village by dark); quest 3376 description (makeshift village, Sharptusk); quest 780 description (battleboars trained to be malicious); quest 1519 description (ritual salve of the Bristleback shamans); quest 24857 description and gameobject 3076 Dirt-stained Map in area 358; warcraft.wiki.gg/wiki/Brambleblade_Ravine (northeastern edge of Red Cloud Mesa, Sharptusk''s large hut)'),
(21504, 1, 215, 4, 0, 0, 'Kodo Rock', 'Kodo Rock is a weathered stone monument on Red Cloud Mesa, standing partway along the trail from Camp Narache to Brambleblade Ravine, and it is easily missed by anyone who is not looking for it. A shaman shrine rests in its shadow, restless spirits of red stone wander the ground nearby, and battleboars from the ravine root through the grass around it. The tauren count it holy ground. Here the young shamans of Camp Narache keep the rite of earth that orc and troll shamans keep at Spirit Rock in Durotar, drinking a sapta that Seer Ravenfeather brews from a salve taken from the Bristleback shamans, and there, she promises, they will see things only their kind know of.', 'warcraft.wiki.gg/wiki/Kodo_Rock (monument near Camp Narache, halfway toward Brambleblade Ravine, hard to spot); zone_areas 637: Shaman Shrine 100028, Redrock Earth Spirit 5890, Minor Manifestation of Earth 5891; quests 1519, 1520, 1521 (descriptions and reward texts); zone_areas 637: Battleboar 2966; data/lore/durotar.json 1403 Spirit Rock and 1431 The Call of Earth (checked for overlap); quest 1519 description (you shall see things only our kind know of)'),
(21505, 1, 215, 5, 0, 0, 'Bloodhoof Village', 'Bloodhoof Village, named for the tribe of Cairne Bloodhoof, sits in the heart of Mulgore within the curve of Stonebull Lake. It is the first true settlement young tauren reach after leaving Red Cloud Mesa, and the busiest place on the plains outside Thunder Bluff. Cairne''s son Baine is its chief, and he sends the young against the threats that trouble the land. Zarlman Two-Moons tends the spirits of the village and brews the Water of the Seers before the tribal fire, Mull Thunderhorn crafts totems to purify the wells, and the old hunter Skorn Whitecloud, old in body but fierce in spirit, still counsels young hunters. Tamed kodo are sold here as mounts, and Innkeeper Kauth welcomes every traveler.', 'warcraft.wiki.gg/wiki/Bloodhoof_Village (named for the Bloodhoof tribe, first settlement after Camp Narache, hub until Thunder Bluff, wild kodo tamed and sold as mounts); quest 763 description (the Chief, Baine Bloodhoof, son of Cairne); quests 767, 771, 772 (Zarlman, tribal fire); quest 748 (Mull); quest 861 reward text (Skorn: body old, spirit burns fiercely); npc_text 822 (Kauth); zone_areas 222: Harb Clawhoof <Kodo Mounts>'),
(21506, 1, 215, 6, 0, 0, 'Stonebull Lake', 'Stonebull Lake is a long, horseshoe-shaped lake that wraps around Bloodhoof Village on three sides, crossed at its narrowest point by the bridge that carries the road north toward Thunder Bluff. Its waters are rich with fish, and Uthan Stillwater teaches the angler''s craft from its banks. On the northern shore the Outrunners of Mulgore fell upon a guarded Venture Company caravan and left its wagons burning, and goblins still creep back to the wreck.', 'warcraft.wiki.gg/wiki/Stonebull_Lake (horseshoe shape, three sides, bridge, plentiful fish); zone_areas 223: Uthan Stillwater 5938 <Fishing Trainer>, Ahab Wheathoof 23618 <The Old Rancher>; quest 749 description (caravan on the northern shore); quest 11129 description; creature_text 23618'),
(21507, 1, 215, 7, 0, 0, 'Palemane Rock', 'Palemane Rock is a cave cut into the mountains of western Mulgore, the den of the Palemane gnolls, who also make camp south of Bloodhoof Village. The gnolls tan, skin and poach the creatures of Mulgore without restraint, and they have scorned every attempt the tauren made to speak with them. For Baine Bloodhoof that disrespect was the end of patience: words, he decided, were no longer the answer. Among their camps prowls a brute called Snagglespear, and travelers who stray too close are met with snarls about fresh meat and more bones to gnaw.', 'warcraft.wiki.gg/wiki/Palemane_Rock (cave in western Mulgore, gnolls inside and camped outside); quest 745 description (south of Bloodhoof and a cave to the west, disrespect communication, slay the wildlife unbridled, words no longer the answer); creature_text 2949, 2950, 2951; DB: Snagglespear 5786 (rare) at -2739,-439, south of Bloodhoof'),
(21508, 1, 215, 8, 0, 0, 'Bael''dun Digsite', 'In the hills northwest of Bloodhoof Village, a dwarven expedition has cut a quarry into the earth at the Bael''dun Digsite. Its diggers and appraisers believe secrets lie buried in the land, and they keep histories of their own people close at hand in the camp, chronicles of the awakening of the dwarves, the War of the Three Hammers and the Battle of Grim Batol. The tauren see the dig very differently. To Baine Bloodhoof, hollowing and defiling the land is no way to earn its teachings, and the digging enrages the kodo of Mulgore. The diggers take their name from Bael''dun, the dwarven stronghold at Bael Modan in the Barrens, where the expedition is based.', 'quest 746 description, request and reward texts; zone_areas 404: Bael''dun Digger 2989, Bael''dun Appraiser 2990, books 175736, 175739, 175750; warcraft.wiki.gg/wiki/Bael''dun_Digsite (dwarven expedition, quarry in the western mountainside, Baine''s warnings); warcraft.wiki.gg/wiki/Bael''dun_Keep (Bael Modan, Barrens); warcraft.wiki.gg/wiki/Bael''dun_Digsite (expedition based at Bael Modan, links to the Bael''dun article)'),
(21509, 1, 215, 9, 0, 0, 'The Sacred Wells', 'Three sacred water wells, named for the Winterhoof, Thunderhorn and Wildmane clans, give water to the people and beasts of Mulgore: Winterhoof southeast of Bloodhoof Village, Thunderhorn to its north, and Wildmane beyond Thunder Bluff. Goblins of the Venture Company, with the hirelings and laborers in their pay, have overrun all three and fouled the water with their poisons. Driving them off is not enough, for a tainted well must be cleansed. The well stones gathered around them are counted among the reagents of the Water of the Seers, and the tauren hold that the waters of Mulgore must flow clean again.', 'quests 748, 754, 758, 760 (descriptions and reward texts: locations, goblins and their servants, cleansing); quest 771 description (well stones); zone_areas 396, 397, 398: Venture Co. Hireling, Laborer, Taskmaster, Worker, Supervisor; Well Stone objects; warcraft.wiki.gg/wiki/Mulgore (Venture Company took the three wells)'),
(21510, 1, 215, 10, 0, 0, 'The Ravaged Caravan', 'Near the northern shore of Stonebull Lake lie the burned wagons of a Venture Company caravan. It traveled under guard, and the Outrunners, who had already lost two of their number in an earlier battle with the goblins, attacked without hesitation and set it ablaze. They left the supply crates behind, trusting their torches to destroy anything of value, yet company salvagers have been seen near the wagons since, and goblin laborers and taskmasters creep back to pick over the wreckage.', 'quest 749 description and reward text; quest 751 description; zone_areas 224: Venture Co. Laborer 2976, Taskmaster 2977, Sealed Supply Crate 2908'),
(21511, 1, 215, 11, 0, 0, 'The Venture Co. Mine', 'The Venture Co. Mine is bored into the eastern mountains of Mulgore, northeast of the Ravaged Caravan. The goblin company was refused mining rights in the tauren homeland and dug anyway, and its workers and supervisors swarm the tunnels hauling ore from the mineral rich hills, while smoke rises from a large fire above the workings. Deep inside, Supervisor Fizsprocket oversees the whole operation.', 'quest 764 description and request text (mine northeast of the caravan, refused mining rights); quest 765 description (Fizsprocket at the mine); page_text 352-354 (Venture Co. Documents: President Razdunk, mineral rich plains, shredders, lumber mill); zone_areas 360: Venture Co. Worker 2978, Supervisor 2979; warcraft.wiki.gg/wiki/Mulgore (mine in the eastern mountain face); DB: Supervisor Fizsprocket 3051 spawn at -1756,-1286 inside the mine; quest 751 description (smoke rising from a large fire in the foothills)'),
(21512, 1, 215, 12, 0, 0, 'The Rolling Plains', 'Southeast of Bloodhoof Village, the Rolling Plains stretch toward the mountains on Mulgore''s border with the Barrens. Windfury harpies and their wind witches nest along the mountain edges away from the road, and Ruul Eagletalon of Bloodhoof sends the young against them as a gauge of their skill before they venture beyond Mulgore. The Windfuries are deadly foes whose strength in battle is matched only by their hunger for fresh meat. Prairie wolf alphas roam the grass, swoops wheel overhead, and a few Galak centaur scouts range across the eastern fields of the tauren homeland.', 'quest 743 description and request text (Ruul, harpies southeast along the mountain edges away from the road); zone_areas 821: Windfury Harpy 2962, Wind Witch 2963, Prairie Wolf Alpha, Swoop, Galak Centaur 2967, Galak Outrunner 2968; DB: harpy spawns average -2308,-653 (east of Bloodhoof), Galak spawns on the eastern edge; warcraft.wiki.gg/wiki/Mulgore (Galak scouting force roamed the plains); posarea sampling: area 821 spans x -2800 to -2400, y -1520 to -960 (east-southeast of Bloodhoof at -2334,-393); warcraft.wiki.gg/wiki/The_Rolling_Plains (southern Mulgore from Bloodhoof to the Barrens border, centaur outriders, harpy nest in the east)'),
(21513, 1, 215, 13, 0, 0, 'The Golden Plains', 'Southeast of Thunder Bluff opens the Golden Plains, a broad basin of grass that the tauren count among the most treasured corners of their homeland and a favored hunting ground. Plainstriders, swoops, prairie wolves and flatland cougars make it a rich country and a dangerous one. Two beasts of ill fame roam its grass: the great cat known as The Rake, and Mazzranache, a strider with demonic red eyes and a venomous bite that has been the bane of hunters for at least two generations.', 'warcraft.wiki.gg/wiki/The_Golden_Plains (basin southeast of Thunder Bluff, treasured part of the homeland, hunting ground); zone_areas 820: Elder Plainstrider, Swoop, Prairie Wolf Alpha, Flatland Cougar, Flatland Prowler, The Rake 5807, Mazzranache 3068; creature_template 5807 family 2 (cat), 3068 family 12 (tallstrider); quest 766 description'),
(21514, 1, 215, 14, 0, 0, 'Windfury Ridge', 'Windfury Ridge runs along the mountains of northern Mulgore, northeast of Thunder Bluff, and it belongs to the Windfury harpies. Their matriarchs and sorceresses nest along the heights and swoop down to seize or slay any traveler who strays too near, and the harpy known as Sister Hatelash hunts the northern hills not far to the west. Wolves and prowling cats roam the slopes below, and so does Arra''chea, a mighty kodo whose horn the high chieftain of Thunder Bluff accepts as proof of a young hunter''s skill in tracking and the hunt.', 'warcraft.wiki.gg/wiki/Windfury_Ridge (harpies swoop on travelers near their nests, feathers used for weddings and feasts); zone_areas 819: Windfury Matriarch 2965, Windfury Sorceress 2964, Flatland Prowler, Prairie Wolf Alpha, Arra''chea 3058; DB: Sister Hatelash 5785 at -660,187 near the ridge; quest 776 description (Cairne asks for the Horn of Arra''chea); posarea sampling: area 819 spans x -760 to -400, y -880 to -320 (northeast of Thunder Bluff); Sister Hatelash spawn -660,188 is area 215, west of the ridge'),
(21515, 1, 215, 15, 0, 0, 'Red Rocks', 'Red Rocks is a formation of red sandstone east of Thunder Bluff and the most sacred burial ground of the tauren. Only the most valiant are laid to rest there: the warriors who helped found and defend Thunder Bluff, and those who gave their lives for their tribes and chieftains. Their ancestral spirits linger among the stones, and young tauren who have drunk the Water of the Seers come here to receive their blessing. Kodo graze on the slopes around it. Lorekeeper Raintotem keeps watch over the graves, though he is too old to defend them now, and a band of Bristleback interlopers has come to ravage the burial site.', 'quest 833 description and reward text; npc_text 17838 (Raintotem gossip); quest 773 description and reward text (Ancestral Spirits, east of Thunder Bluff); zone_areas 225: Ancestral Spirit 2994, Lorekeeper Raintotem 3233, Bristleback Interloper 3232, Kodo Calf, Bull, Matriarch; warcraft.wiki.gg/wiki/Red_Rocks (red sandstone, sacred burial site)'),
(21516, 2, 215, 1, 2, 0, 'Baine Bloodhoof', 'Baine is the son of Cairne Bloodhoof and Tamaala, and chief of Bloodhoof Village. After the Third War, centaur led by Khiragg raided the tauren village and carried him off, and his grieving father lost the will to lead, until the wanderer Rexxar found the centaur camp and brought Baine home. Since then he has served as Cairne''s adviser and leads the tribe whenever his father is away. Calm and thoughtful, he holds that the land has been good to the tauren and that respect for it is everything. He teaches that life and death are a circle, sets himself against the dwarves hollowing the western hills, and sends the young against the Palemane gnolls who slaughter Mulgore''s beasts.', 'warcraft.wiki.gg/wiki/Baine_Bloodhoof (parents, kidnapping by Khiragg''s centaur and rescue by Rexxar in Warcraft III, adviser, tribal leader when Cairne absent, calm and diplomatic); quest_greeting 2993; quest 745 description and reward text (death and life are a circle); quest 746 description; quest 763 description (Chief, son of Cairne)'),
(21517, 2, 215, 2, 2, 0, 'The Hawkwinds', 'The Hawkwind family keeps the hearth of Camp Narache. Chief Hawkwind, an old friend of Baine Bloodhoof, has seen many eager young tauren pass through his camp and warns them that eagerness is no substitute for wisdom and experience. He sends each one toward the Rites of the Earthmother bearing a totem of his own carving, which Baine knows at a glance. His mother, Greatmother Hawkwind, still draws water from the well southeast of the camp, slower than she once was but no less devoted to the tribe, and she teaches that even the humblest task can earn the notice of elders. The chief''s son Grull is a hunter who reminds the young that prey is never mere trophy.', 'quest_greeting 2981; quests 752, 753 (Greatmother is the Chief''s mother); quest 747 description (Grull: my father, Chief Hawkwind); quest 750 description; quest 763 description and reward text (Totem of Hawkwind, my good friend)'),
(21518, 2, 215, 3, 2, 0, 'Mull Thunderhorn', 'Mull Thunderhorn is a mystic of Bloodhoof Village who has taken up the cleansing of Mulgore''s sacred wells since the goblins poisoned them. He cannot heal the water alone. The land itself must offer its aid, so he asks for paws, talons, claws and teeth from the creatures of the plains and, through trance and chant, binds their power into totems of cleansing. He feels every offering deeply, his spirit swelling with sadness and with pride at the sacrifice of the beasts. Goblins, he believes, will never learn the difference between contending with the land and living in harmony with it.', 'quests 748, 754, 756, 758, 759, 760 (descriptions and reward texts); creature_text 2948 (trance, chant, ritual)'),
(21519, 2, 215, 4, 2, 0, 'Morin Cloudstalker', 'Morin Cloudstalker is one of the Outrunners, whose duty is to keep safe those who travel the plains of Mulgore and to punish any who threaten the tauren homeland. He keeps his post on the road east of Bloodhoof Village. After two Outrunners fell in a clash with the Venture Company, Morin''s band attacked a goblin caravan near Stonebull Lake and burned it, and now that salvagers have been seen at the wreck he wants to know what its crates held. Tauren, he says, are not ones to mince words, and they have other ways of getting a message across.', 'quest_greeting 2988 (Outrunners'' duty); quests 749, 751, 764, 765 (descriptions, request and reward texts); DB: Morin 2988 at -2369,-877, area 215, east of Bloodhoof; warcraft.wiki.gg/wiki/Morin_Cloudstalker (on the road from Bloodhoof Village); quest 751 request text'),
(21520, 2, 215, 5, 2, 0, 'Zarlman Two-Moons', 'Zarlman Two-Moons is the spiritual leader of Bloodhoof Village, and he always seems to sense when a young tauren walking the Rites of the Earthmother is on the way to him. He guides them through the Rite of Vision, teaching that the land is the people''s most holy provider. From stones gathered at the water wells and ambercorn fallen beneath Mulgore''s great trees, he brews the Water of the Seers, chanting as he mixes the reagents before the tribal fire. Those who drink it see a vision take shape before the flames, and must follow wherever it leads.', 'quests 767, 771, 772 (descriptions and reward texts); creature_text 3054; warcraft.wiki.gg/wiki/Bloodhoof_Village (Zarlman attends to the spiritual needs of the tribe)'),
(21521, 2, 215, 6, 0, 0, 'Ghost Howl', 'Ghost Howl is a massive white wolf who roams the plains about the foot of Thunder Bluff. The tauren once respected him for his part in the battles against the Burning Legion, but a demon dealt him a terrible wound that never healed, and its torment has turned him against the tauren and their allies. Now he lives out his last days alone in Mulgore, his ragged hide still bearing the demon''s wound.', 'quest 770 description and reward text (wound from battles against the Burning Legion, Skorn''s reaction); creature_loot_template 3056 drops item 4854 Demon Scarred Cloak, which starts quest 770; warcraft.wiki.gg/wiki/Ghost_Howl (massive white wolf, respected by the tauren, unhealable wound, roams near Thunder Bluff); DB: Ghost Howl 3056 spawn at -758,132 (area 215)'),
(21522, 2, 215, 7, 0, 0, 'Chief Sharptusk Thornmantle', 'Chief Sharptusk Thornmantle leads the Bristleback quilboar of Brambleblade Ravine, and under him the tribe wages an unending war on the tauren of Red Cloud Mesa. His raiders ambush hunting parties, steal from Camp Narache by night and train their battleboars to savagery. Sharptusk himself keeps to a large hut at the back of the ravine, in the heart of his tribe''s makeshift village. Others have gone after him and failed. To the braves of the mesa he is the finest kind of quarry, one cunning enough to hunt the hunter back.', 'quest 3376 description and request text (continued war, makeshift village, others have failed, a quarry cunning enough to hunt us back); quests 757, 780, 24857; warcraft.wiki.gg/wiki/Brambleblade_Ravine (large hut at the back of the ravine)'),
(21523, 2, 215, 8, 0, 0, 'Supervisor Fizsprocket', 'Supervisor Fizsprocket runs the Venture Company''s operation in Mulgore from deep inside the company mine in the eastern hills, northeast of the Ravaged Caravan. His workers and supervisors swarm the tunnels hauling ore out of the hills, though the tauren refused the company mining rights, and the Outrunners have already burned one of its guarded caravans on the shore of Stonebull Lake. Above the workings the sounds of work carry across the foothills, and smoke rises from a large fire.', 'quest 765 description (mastermind, plans to drive us from our lands); page_text 352-354 (Venture Co. Documents); DB: Supervisor Fizsprocket 3051 spawn inside the Venture Co. Mine; quest 764 request text (mining rights refused); quest 749 description (guarded caravan burned); quest 751 description (sounds of work and smoke in the foothills)'),
(21524, 2, 215, 9, 0, 0, 'Mazzranache', 'Mazzranache is a strider of dark reputation that stalks the Golden Plains. Maur Raincaller of Bloodhoof Village grew up on his grandfather''s tales of battles with the beast: its demonic red eyes, its razor-sharp talons and its venomous bite. Crossing the plains, Maur met it himself, and it tore a nasty bite from his shoulder. Now he burns with fever and drifts into delirious nightmares, fearing the infection will be the death of him unless he can make a remedy of wolf heart, cougar femur, plainstrider scale and swoop gizzard.', 'quest 766 description, request and reward texts; creature_template 3068 family 12 (tallstrider); DB: Mazzranache 3068 at -1731,-541, area 820 The Golden Plains'),
(21525, 3, 215, 1, 2, 0, 'Trials of Red Cloud Mesa', 'A young tauren earns a place in the tribe through deeds, and Camp Narache offers plenty. Grull Hawkwind first sends novices after plainstriders for meat and feathers, then after the mountain cougars of the southern hills, whose pelts clothe the children and mend the tents, and at last against the battleboars the Bristlebacks have trained to raid the hunting grounds, whose snouts and flanks make stew for the young. Brave Windfeather asks for something harder, the head of Chief Sharptusk Thornmantle, a quarry others have failed to take. Not every trial is fought. Antur Fallow, worn out in the middle of his own Rite of Strength, begs someone to carry his father''s furs down to the inn at Bloodhoof Village.', 'quests 747, 750, 780 (descriptions and reward texts); quest 3376 description and reward text; quest 24857 description and reward text (started by gameobject 3076 Dirt-stained Map); quest 1656 description and reward text'),
(21526, 3, 215, 2, 2, 0, 'Rites of the Earthmother', 'The Rites of the Earthmother are the steps by which a young tauren earns the respect of the elders of Thunder Bluff. They begin with a humble task, a pitcher of water carried from Greatmother Hawkwind''s well southeast of Camp Narache, for even the smallest service can win an elder''s notice. Three rites follow, of strength, of vision and of wisdom. For the first, Chief Hawkwind sends the youth to Seer Graytongue, whose abode is tucked into the hills south of the camp, and the Rite of Strength is a test of bravery against the Bristlebacks of Brambleblade Ravine, who ambush hunting parties and steal from the camp by dark. Beyond it the road leads down from the mesa, and in time toward Thunder Bluff itself.', 'quests 752, 753, 755, 757, 763, 767, 771, 772, 773, 775 (descriptions and reward texts); creature_text 2983 The Plains Vision (howls); creature_text 2984 (Seer Wiserunner); DB: Seer Wiserunner 2984 at -1509,367, area 215'),
(21527, 3, 215, 3, 2, 0, 'The Poisoned Wells', 'When the Venture Company''s goblins and their servants fouled the sacred wells of Mulgore, Mull Thunderhorn of Bloodhoof Village set out to heal them, one at a time. Each well needs its own totem of cleansing, and each totem demands an offering from the land. For the Winterhoof well southeast of the village he asks the paws of prairie wolves and the talons of plainstriders. For the Thunderhorn well to the north, the claws of stalkers and cougars, whose purity in the hunt he holds vital to the work. For the Wildmane well, last and farthest, beyond Thunder Bluff, the teeth of prairie wolf alphas, a sacrifice he feels keenly. At each well the totem must be carried past the goblins and a ritual performed.', 'quests 748, 754, 756, 758, 759, 760 (descriptions and reward texts); quest 759 reward text (feels the sacrifice of the land)'),
(21528, 3, 215, 4, 2, 0, 'The Venture Company in Mulgore', 'The Outrunners had already lost two of their own to the Venture Company when they found a goblin caravan traveling under guard on the northern shore of Stonebull Lake. They fell on it at once and burned it, leaving the supply crates behind in the belief that their torches had destroyed anything of value. But company salvagers have since been seen picking through the wreck, and Morin Cloudstalker, who keeps the Outrunners'' watch on the road east of Bloodhoof Village, wants someone to go and look inside the crates. If the goblins mean to exploit the tauren homeland as they have exploited other lands, the Outrunners will put an end to it.', 'quests 749, 751, 764, 765 (descriptions, request and reward texts); page_text 352-354 (Venture Co. Documents); gameobject 2908 Sealed Supply Crate starts 751'),
(21529, 3, 215, 5, 2, 0, 'Sharing the Land', 'Baine Bloodhoof teaches that the land has been good to the tauren and must be respected in return, and two intruders in Mulgore have refused that lesson. To the south and west, the Palemane gnolls kill the creatures of the plains without restraint and have scorned every attempt to speak with them, so Baine sends the young to cut down their tanners, skinners and poachers, so that they may see how terrible even a small threat to the land can become if left unchecked. To the northwest, dwarves are hollowing the hills at the Bael''dun Digsite in search of the earth''s secrets, and their digging enrages the kodo. There Baine asks not for blood but for their tools: picks taken from the dig and smashed at a forge.', 'quest 745 description, request and reward texts; quest 746 description, request and reward texts; quest_greeting 2993');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(21503, 1, 0, 255, 'Studied with care, the dirt-stained map gives up its secret. It holds plans drawn up by the Bristleback warchief for an extended siege of Camp Narache, proof that the quilboar mean to do far more than raid the hunting grounds, and news that Chief Hawkwind must hear at once.', 'quest 24857 description (started by gameobject 3076 Dirt-stained Map, area 358)'),
(21504, 1, 0, 255, 'Those who drink the sapta here with proper humility find the earth answering them. A manifestation of earth rises at the shrine and welcomes them, then gives a piece of rough quartz to carry back to Ravenfeather as the heart of their first totem, for even the smallest of things, it says, can outlast mountains.', 'quest 1520 reward text (Minor Manifestation of Earth 5891 ends 1520); quest 1521 description (rough quartz, heart of the totem; started by 5891)'),
(21506, 1, 8, 255, 'Near the village an old rancher, Ahab Wheathoof, frets over his prized puppy Kyle, who has run off again. Ahab calls for the dog and asks passersby for help, for Kyle can be coaxed home only with tender strider meat.', 'quest 11129 description (added in patch 2.1.2, warcraft.wiki.gg/wiki/Kyle''s_Gone_Missing!); creature_text 23618'),
(21510, 1, 0, 255, 'Not every crate burned. The survivors are stamped on every side with the sign of the Venture Co. Mining Division, with notes that their contents are bound for processing at one of the company''s central plants. Pried open, one proves tightly packed with ore and minerals, more evidence of goblin mining in Mulgore, with a bound sheaf of papers lying on top.', 'quest 749 reward text (crate 2908 ends 749); quest 751 description (crate 2908 starts 751)'),
(21511, 1, 0, 255, 'Papers salvaged from the caravan show where the orders come from. A letter to Fizsprocket encloses a list of the equipment he requisitioned, approved by the company president, Razdunk, presses for better production from Mulgore, and promises the newest shredders and the makings of a lumber mill besides, for the board believes the plains have timber to offer as well as ore.', 'quest 751 StartItem 4834 Venture Co. Documents, PageText 352; page_text 352-354'),
(21518, 1, 0, 255, 'As the wells begin to run clean, Mull tells of a dream in which the ancestors of the Thunderhorn clan spoke to him, praising the deed done at the well that bears their name, and in their gratitude he passes on a gift to the one who performed the ritual.', 'quest 758 reward text'),
(21518, 2, 0, 255, 'When the Wildmane well, the last and farthest, is cleansed, Mull declares the land healed and Bloodhoof Village grateful. He prays that the wind may whisper the deed for a hundred seasons, and that the waters of Mulgore remain clean forever.', 'quest 760 reward text'),
(21519, 1, 0, 255, 'The papers recovered from the caravan''s crates confirm his fears. The Venture Company is mining Mulgore and means to rob the tauren of their natural resources, and Morin, glad at least to know it for certain, resolves that something must be done about it.', 'quest 751 reward text'),
(21519, 2, 0, 255, 'The documents also show that the company has laid many plans to drive the tauren from their land and plunder it at will, and Morin wants the mastermind behind them dead. When Supervisor Fizsprocket falls in his mine and his clipboard is brought back, Morin''s anger cools a little, and he sets about searching the goblin''s effects for word of what the company plans next.', 'quest 765 description and reward text'),
(21521, 1, 0, 255, 'In Bloodhoof Village the old hunter Skorn Whitecloud can scarcely believe his eyes when proof of the great wolf''s death is brought to him. He looks on the hunter who did it with new respect, offers one of his own weapons for their hunts, and hopes that Ghost Howl''s spirit has at last found peace.', 'quest 770 reward text (ender Skorn Whitecloud 3052)'),
(21522, 1, 0, 255, 'A dirt-stained map from the ravine shows how far the Bristlebacks mean to take their war. It holds plans drawn up by the Bristleback warchief for an extended siege of Camp Narache, a far greater threat than the raids the camp has endured so far.', 'quest 24857 description'),
(21522, 2, 0, 255, 'Sharptusk''s head is carried at last to Brave Windfeather on Red Cloud Mesa. Justice has been served by swift action, the brave declares, and the deed will stand as a warning to all who would threaten the tauren''s home.', 'quest 3376 reward text (ender Brave Windfeather 3209)'),
(21523, 1, 0, 255, 'Papers taken from the burned caravan are addressed to him. At President Razdunk''s bidding, his superiors remind him of the company''s ambitions across Kalimdor, note that its drilling and mining outposts in the Barrens already turn a profit, and press him for production numbers from Mulgore that have yet to arrive. Even so, the board has approved the equipment he requisitioned, the newest shredders and the makings of a lumber mill among it.', 'page_text 352-354 (item 4834 Venture Co. Documents, StartItem of 751)'),
(21523, 2, 0, 255, 'Reading the documents, Morin Cloudstalker of the Outrunners names Fizsprocket the mastermind behind the company''s plans to drive the tauren from their land so that it might be plundered at will. He wants the supervisor dead and his clipboard brought back for study.', 'quest 765 description'),
(21524, 1, 0, 255, 'With the ingredients brought to him, Maur brews a remedy that stops the spread of the infection and will cure it in time, and he owes his life to the one who gathered them. Yet he will never forget the screeching call as Mazzranache came upon him, nor the blaze of color as its beak came down.', 'quest 766 reward text'),
(21525, 1, 0, 255, 'In Brambleblade Ravine lies a dirt-stained map, and studied closely it proves to hold plans drawn up by the Bristleback warchief for an extended siege of Camp Narache. The quilboar mean to do far more than raid, and whoever finds the plans must hurry them to Chief Hawkwind.', 'quest 24857 description'),
(21525, 2, 0, 255, 'The plans alarm Chief Hawkwind, but forewarned he can call on his brethren in Bloodhoof Village to help thwart the attack. The warning carried out of the ravine, he says, has saved the lives of many tauren.', 'quest 24857 reward text'),
(21525, 3, 0, 255, 'Chief Sharptusk falls, and his head is laid before Brave Windfeather. Justice has been served by swift action, the brave declares, and the deed will stand as a warning to all who would threaten the tauren''s home.', 'quest 3376 reward text'),
(21525, 4, 0, 255, 'The furs reach Innkeeper Kauth sooner than he expected. They will make good blankets for any who stay at his inn, which, he says, is always open to every one of their people, for a good night''s rest can make a great difference to a traveler.', 'quest 1656 reward text (ender Innkeeper Kauth 6747)'),
(21526, 1, 0, 255, 'The Rite of Strength passed, Chief Hawkwind sends the youth down the road to Bloodhoof Village with a totem of his own carving for Baine Bloodhoof, son of Cairne, who will know the carvings and help the youth along the path. Two tests remain.', 'quest 757 reward text; quest 763 description (offered by Chief Hawkwind after 757)'),
(21526, 2, 0, 255, 'In Bloodhoof the Rite of Vision begins. Zarlman Two-Moons, who always senses who walks the rites, brews the Water of the Seers from well stones and ambercorn, chanting before the tribal fire. Once it is drunk a vision takes shape before the flames, howls, and leads the youth across the plains to Seer Wiserunner, who has been expecting them and declares the Rite of Vision passed.', 'quests 767, 771, 772 (descriptions and reward texts); creature_text 3054, 2983 The Plains Vision, 2984 Seer Wiserunner (ender of 772)'),
(21526, 3, 0, 255, 'The Rite of Wisdom ends at Red Rocks east of Thunder Bluff. There the ancestral spirits, the mighty tauren who gave their lives to found and protect the city, pass their duty of protection on to the young tauren, who may then enter Thunder Bluff with pride and seek out Cairne Bloodhoof atop its highest mesa.', 'quest 773 description and reward text (Ancestral Spirit 2994); quest 775 description (offered by the Ancestral Spirit; trigger left to Thunder Bluff)'),
(21527, 1, 0, 255, 'The Winterhoof well is cleansed first. Word of the ritual reaches Mull moments after it is done, and already the beasts near the well drink from it eagerly. It is a great thing, he says, done for the land and for the tauren people.', 'quest 754 reward text'),
(21527, 2, 0, 255, 'The Thunderhorn well follows. The ancestors of the Thunderhorn clan speak to Mull in a dream, praising the one who cleansed the well that bears their name, and they send a gift in their gratitude.', 'quest 758 reward text'),
(21527, 3, 0, 255, 'Last of all the Wildmane well north of Thunder Bluff is purified, and the goblins'' poisons are gone from all three. Mull declares the land healed and Bloodhoof Village grateful, and prays that the wind will whisper the deed for a hundred seasons and the waters of Mulgore remain clean forever.', 'quest 760 description and reward text'),
(21528, 1, 0, 255, 'Some crates survived the fire. Each is stamped with the sign of the Venture Co. Mining Division and marked for processing at one of the company''s central plants, and inside lie ore and minerals packed tight, with a sheaf of papers on top. Up in the foothills to the east, the sounds of work carry on the wind and smoke rises from a large fire.', 'quest 749 reward text; quest 751 description'),
(21528, 2, 0, 255, 'The papers are a letter to Supervisor Fizsprocket, enclosing a list of equipment approved by President Razdunk, urging greater production from the mineral rich plains and promising shredders and a lumber mill besides. To Morin they prove that the company means to rob the tauren of their natural resources, and he resolves that something must be done.', 'page_text 352-354 (Venture Co. Documents); quest 751 reward text'),
(21528, 3, 0, 255, 'The company had been refused mining rights in Mulgore and dug anyway, so Morin sends the goblins a message in the tauren way. Workers and supervisors are struck down in the mine northeast of the caravan, a signal, Morin judges, that no goblin could misread: the tauren will not let their land be robbed without protest.', 'quest 764 description, request and reward texts'),
(21528, 4, 0, 255, 'The documents also lay bare the company''s plans to drive the tauren from their land so that it might be plundered at will, and the mastermind behind them is Supervisor Fizsprocket. He is slain in his mine and his clipboard carried back to Morin, who means to search it for whatever the Venture Company has planned next.', 'quest 765 description and reward text'),
(21529, 1, 0, 255, 'When the Palemane hunters have fallen, Baine is glad the task was taken seriously. Had the gnolls respected the land and its creatures, he says, the conflict would never have come. Death and life, he reminds them, are a circle and a necessity, and neither can exist without the other: a lesson he asks the young never to forget.', 'quest 745 request and reward texts'),
(21529, 2, 0, 255, 'The broken tools brought back from the dig will calm the beasts of Mulgore, Baine says, and, spirits willing, they will teach the dwarves that hollowing the land is not the path to knowledge.', 'quest 746 reward text');
